package dev.minesino.client.gui.games;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import dev.minesino.client.ClientState;
import dev.minesino.client.gui.Anim;
import dev.minesino.client.gui.TabletData;
import dev.minesino.client.gui.Theme;
import dev.minesino.client.gui.Ui;
import dev.minesino.client.gui.widget.Button;
import dev.minesino.economy.Json;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.sounds.SoundEvents;

/** Plinko: the ball follows exactly the left/right path generated by the server. */
public class PlinkoPage extends GamePage {
	private static final String[] RISKS = {"low", "medium", "high"};
	private static final int[] ROWS = {8, 12, 16};
	private String risk = "medium";
	private int rows = 12;
	private int[] path;
	private int bin = -1;
	private int lastRowSound = -1;
	private float top, spacing, cx;

	public PlinkoPage() {
		super("plinko");
	}

	@Override
	protected float layoutSide(float x, float y, float w) {
		float cw = (w - 8) / 3;
		for (int i = 0; i < 3; i++) {
			String r = RISKS[i];
			add(new Button(() -> Ui.tr("minesino.plinko." + r), Button.Style.CHIP, () -> risk = r)
				.select(() -> risk.equals(r)).when(() -> !animating)).bounds(x + i * (cw + 4), y, cw, 14);
		}
		for (int i = 0; i < 3; i++) {
			int n = ROWS[i];
			add(new Button(() -> Integer.toString(n), Button.Style.CHIP, () -> {
				rows = n;
				layoutBoard(bx, by, bw, bh);
			}).select(() -> rows == n).when(() -> !animating)).bounds(x + i * (cw + 4), y + 18, cw, 14);
		}
		return y + 38;
	}

	@Override
	protected void layoutBoard(float x, float y, float w, float h) {
		spacing = Math.min((w - 16) / (rows + 2), (h - 40) / (rows + 1));
		top = y + 14;
		cx = x + w / 2;
	}

	private long[] table() {
		JsonObject tables = info.has("tables") ? info.getAsJsonObject("tables") : new JsonObject();
		String key = risk + "_" + rows;
		return tables.has(key) ? TabletData.longs(tables.getAsJsonArray(key)) : new long[rows + 1];
	}

	@Override
	protected String playLabel() {
		return busy || animating ? "…" : Ui.tr("minesino.plinko.drop");
	}

	@Override
	protected void onPlay() {
		JsonObject p = new JsonObject();
		p.addProperty("risk", risk);
		p.addProperty("rows", rows);
		bin = -1;
		play("drop", p);
	}

	@Override
	protected long animationMs() {
		return 140L * rows + 250;
	}

	@Override
	protected void startAnimation(JsonObject data) {
		JsonArray a = data.getAsJsonArray("path");
		path = new int[a.size()];
		for (int i = 0; i < path.length; i++) path[i] = a.get(i).getAsInt();
		lastRowSound = -1;
	}

	@Override
	protected void finishAnimation() {
		bin = result == null ? -1 : Json.getInt(result, "bin", -1);
		super.finishAnimation();
	}

	private float pegX(int row, int j) {
		return cx + (j - (row + 2) / 2f) * spacing;
	}

	@Override
	protected void renderBoard(GuiGraphicsExtractor g, int mx, int my, float dt) {
		for (int r = 0; r < rows; r++) {
			for (int j = 0; j < r + 3; j++) {
				Ui.circle(g, pegX(r, j), top + r * spacing, Math.max(1.1f, spacing * 0.12f), 0xFFDCD6EA);
			}
		}
		long[] mults = table();
		float binY = top + rows * spacing + 2;
		float binW = spacing - 1.5f;
		for (int k = 0; k <= rows; k++) {
			float x0 = cx + (k - rows / 2f) * spacing - binW / 2;
			float edge = Math.abs(k - rows / 2f) / (rows / 2f);
			int color = Theme.lerp(0xFFF59E0B, 0xFFE11D48, edge);
			if (k < mults.length && mults[k] < 100) color = Theme.lerp(0xFF6D28D9, 0xFFF59E0B, edge * 1.5f);
			boolean hit = k == bin && !animating;
			if (hit) Ui.glow(g, x0, binY, binW, 12, 6, Theme.alpha(color, 0.7f * Anim.pulse(0.8f) + 0.3f));
			Ui.round(g, x0, binY + (hit ? 2 : 0), binW, 12, 2.5f, color);
			String label = k < mults.length ? mult(mults[k]) : "";
			float k2 = Math.min(0.75f, (binW - 2) / Math.max(1, Ui.width(label)));
			Ui.scaledCenter(g, label, x0 + binW / 2, binY + 3.5f + (hit ? 2 : 0), k2, 0xFF1A0F05, false);
		}
		if (animating && path != null) {
			float t = Anim.progress(animStart, animationMs()) * (animationMs()) / 140f;
			int row = (int) Math.min(t, path.length);
			float frac = Math.min(1, t - row);
			int rights = 0;
			for (int i = 0; i < row && i < path.length; i++) rights += path[i];
			float xFrom = cx + (rights - row / 2f) * spacing;
			float yFrom = top - spacing * 0.6f + row * spacing;
			float px, py;
			if (row < path.length) {
				float xTo = cx + (rights + path[row] - (row + 1) / 2f) * spacing;
				px = xFrom + (xTo - xFrom) * frac;
				py = yFrom + spacing * frac - (float) Math.sin(frac * Math.PI) * spacing * 0.35f;
				if (row != lastRowSound) {
					lastRowSound = row;
					Ui.sound(SoundEvents.NOTE_BLOCK_HAT.value(), 1.4f + row * 0.03f, 0.25f);
				}
			} else {
				px = xFrom;
				py = binY - 2;
			}
			Ui.glow(g, px - 3, py - 3, 6, 6, 4, Theme.alpha(Theme.PINK, 0.6f));
			Ui.circle(g, px, py, Math.max(2.2f, spacing * 0.28f), Theme.PINK);
			Ui.circle(g, px - 0.6f, py - 0.6f, Math.max(0.8f, spacing * 0.1f), 0xFFFFE4F1);
		}
	}

	@Override
	protected void renderSideInfo(GuiGraphicsExtractor g, float x, float y, float w) {
		long[] m = table();
		long max = 0;
		for (long v : m) max = Math.max(max, v);
		if (bet != null && bet.bet() > 0) {
			Ui.text(g, Ui.tr("minesino.plinko.max_win", ClientState.money(bet.bet() * max / 100)), x, y, Theme.MUTED);
		}
	}

	@Override
	protected String recentLabel(JsonObject o) {
		return "×" + mult(Json.getLong(o, "mult", 0)) + " · " + Ui.tr("minesino.plinko." + Json.getString(o, "risk", "low"));
	}
}
